USE dbMaster;
IF OBJECT_ID('dbo.tblBOMHeaders','U') IS NULL CREATE TABLE dbo.tblBOMHeaders(BOMId INT IDENTITY PRIMARY KEY,FGProductId INT NOT NULL REFERENCES dbo.tblProducts(ProductId),VersionNo INT NOT NULL,BaseQuantity DECIMAL(18,6) NOT NULL CHECK(BaseQuantity>0),Status VARCHAR(10) NOT NULL DEFAULT 'DRAFT' CHECK(Status IN('DRAFT','ACTIVE','ARCHIVED')),Note NVARCHAR(500) NULL,Revision INT NOT NULL DEFAULT 1,CreatedBy NVARCHAR(50) NOT NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME(),ActivatedBy NVARCHAR(50) NULL,ActivatedAt DATETIME2 NULL,CONSTRAINT UQ_BOM_Version UNIQUE(FGProductId,VersionNo));
IF OBJECT_ID('dbo.tblBOMLines','U') IS NULL CREATE TABLE dbo.tblBOMLines(BOMLineId INT IDENTITY PRIMARY KEY,BOMId INT NOT NULL REFERENCES dbo.tblBOMHeaders(BOMId),ComponentProductId INT NOT NULL REFERENCES dbo.tblProducts(ProductId),Quantity DECIMAL(18,6) NOT NULL CHECK(Quantity>0),UnitId INT NOT NULL REFERENCES dbo.tblUnits(UnitId),CONSTRAINT UQ_BOM_Component UNIQUE(BOMId,ComponentProductId));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('dbo.tblBOMHeaders') AND name='UQ_BOM_Active') CREATE UNIQUE INDEX UQ_BOM_Active ON dbo.tblBOMHeaders(FGProductId) WHERE Status='ACTIVE';
